import{_ as e,o as a,c as l,j as t,a as r,a3 as i}from"./chunks/framework.BPaanrMb.js";const p=JSON.parse('{"title":"从需求沟通到试点部署","description":"用五个客户里程碑展示自动驾驶短途运输项目从需求沟通、场景评估、方案设计、单线路试点到扩展决策的过程。","frontmatter":{"title":"从需求沟通到试点部署","description":"用五个客户里程碑展示自动驾驶短途运输项目从需求沟通、场景评估、方案设计、单线路试点到扩展决策的过程。","status":"设计建议","content_type":"delivery","keywords":["交付流程","试点部署","需求沟通","现场调研","方案设计","验收指标"],"scope":"WheelOS 短途自动驾驶运输项目的客户交付与试点方法","decision_summary":"先验证一条线路和一类货物，再决定是否扩展；每个里程碑都有输入、交付物和通过条件。","best_for":["单线路试点","固定路线运输","可量化的运营指标","分阶段投资"],"not_for":["跳过现场评估直接部署","未确认底盘就承诺运行","没有证据就宣称量产"],"next_action":"先完成场景适配判断，再准备货物、起终点、频次、车辆和当前成本信息。","cta_url":"mailto:support@wheelos.cn?subject=WheelOS%20pilot%20delivery%20plan"},"headers":[],"relativePath":"solutions/delivery-process.md","filePath":"solutions/delivery-process.md","lastUpdated":1794551845000}'),o={name:"solutions/delivery-process.md"};function h(s,d,n,c,b,u){return a(),l("div",null,[...d[0]||(d[0]=[t("h1",{id:"从需求沟通到试点部署",tabindex:"-1"},[r("从需求沟通到试点部署 "),t("a",{class:"header-anchor",href:"#从需求沟通到试点部署","aria-label":'Permalink to "从需求沟通到试点部署"'},"​")],-1),t("blockquote",null,[t("p",null,"不建议一开始就建设完整无人运输网络。先选一条合适线路，验证业务价值和运行条件，再逐步扩大。整个过程像建房子：地基、结构、水电、验收和试运行都必须看得见。")],-1),t("div",{class:"delivery-flow",role:"list","aria-label":"五个客户交付阶段"},[t("div",{class:"delivery-flow__node",role:"listitem"},[t("span",null,"01"),t("strong",null,"需求沟通")]),t("div",{class:"delivery-flow__arrow","aria-hidden":"true"},"→"),t("div",{class:"delivery-flow__node",role:"listitem"},[t("span",null,"02"),t("strong",null,"初步场景评估")]),t("div",{class:"delivery-flow__arrow","aria-hidden":"true"},"→"),t("div",{class:"delivery-flow__node",role:"listitem"},[t("span",null,"03"),t("strong",null,"现场调研与方案设计")]),t("div",{class:"delivery-flow__arrow","aria-hidden":"true"},"→"),t("div",{class:"delivery-flow__node",role:"listitem"},[t("span",null,"04"),t("strong",null,"小规模试点")]),t("div",{class:"delivery-flow__arrow","aria-hidden":"true"},"→"),t("div",{class:"delivery-flow__node",role:"listitem"},[t("span",null,"05"),t("strong",null,"复盘与扩展决策")])],-1),i('<h2 id="五个客户里程碑" tabindex="-1">五个客户里程碑 <a class="header-anchor" href="#五个客户里程碑" aria-label="Permalink to &quot;五个客户里程碑&quot;">​</a></h2><h3 id="_1-提交基本需求" tabindex="-1">1. 提交基本需求 <a class="header-anchor" href="#_1-提交基本需求" aria-label="Permalink to &quot;1. 提交基本需求&quot;">​</a></h3><table tabindex="0"><thead><tr><th>客户会看到</th><th>需要提供</th><th>WheelOS 交付</th><th>通过条件</th></tr></thead><tbody><tr><td>场景信息清单、初步沟通记录</td><td>运输货物、起点终点、运输频次、运行区域、现有车辆和人员、特殊要求</td><td>需求整理、缺失信息清单和下一步安排</td><td>运输任务和业务目标可以描述清楚</td></tr></tbody></table><h3 id="_2-初步场景评估" tabindex="-1">2. 初步场景评估 <a class="header-anchor" href="#_2-初步场景评估" aria-label="Permalink to &quot;2. 初步场景评估&quot;">​</a></h3><table tabindex="0"><thead><tr><th>客户会看到</th><th>需要提供</th><th>WheelOS 交付</th><th>通过条件</th></tr></thead><tbody><tr><td>五关判断摘要、主要风险和待确认项</td><td>真实任务数据、线路条件、车辆基础、安全责任和当前成本</td><td>场景适配建议、初步价值判断和是否需要现场调研</td><td>没有未解决的硬性阻断项</td></tr></tbody></table><p>可直接使用<a href="/solutions/fit-assessment">场景适配判断工具</a>。</p><h3 id="_3-现场调研与方案设计" tabindex="-1">3. 现场调研与方案设计 <a class="header-anchor" href="#_3-现场调研与方案设计" aria-label="Permalink to &quot;3. 现场调研与方案设计&quot;">​</a></h3><table tabindex="0"><thead><tr><th>客户会看到</th><th>双方共同确认</th><th>WheelOS 交付</th><th>通过条件</th></tr></thead><tbody><tr><td>现场问题、车辆接口、路线和风险清单</td><td>运行设计域、站点、装卸、责任人、验收指标和项目范围</td><td>方案边界、车辆与传感器建议、集成计划、责任矩阵和报价输入</td><td>安全、法规、底盘和各方责任可落实</td></tr></tbody></table><h3 id="_4-小规模试点与效果验证" tabindex="-1">4. 小规模试点与效果验证 <a class="header-anchor" href="#_4-小规模试点与效果验证" aria-label="Permalink to &quot;4. 小规模试点与效果验证&quot;">​</a></h3><table tabindex="0"><thead><tr><th>客户会看到</th><th>试点范围</th><th>WheelOS 交付</th><th>通过条件</th></tr></thead><tbody><tr><td>每日任务看板、异常清单、指标和周报</td><td>一条线路或一类货物</td><td>系统集成、标定、运行日志、问题闭环和阶段报告</td><td>达到约定指标，且风险可控、问题可追踪</td></tr></tbody></table><p>试点至少记录：</p><table tabindex="0"><thead><tr><th>指标</th><th>基线</th><th>试点结果</th></tr></thead><tbody><tr><td>运输频次</td><td>每日任务数、班次和高峰时段</td><td>实际完成任务数</td></tr><tr><td>人工投入</td><td>司机、搬运、调度和人工干预小时</td><td>试点期间人工投入</td></tr><tr><td>车辆利用率</td><td>有效运行、等待和空驶时间</td><td>单车有效利用率</td></tr><tr><td>准点率</td><td>约定时间窗口</td><td>按窗口完成任务比例</td></tr><tr><td>异常次数</td><td>接管、急停、阻塞和人工恢复</td><td>每百次任务异常次数</td></tr><tr><td>单位成本</td><td>每次任务、公里或托盘成本</td><td>试点实际单位成本</td></tr><tr><td>安全事件</td><td>分级规则</td><td>碰撞、险情、违规和现场风险</td></tr></tbody></table><p>这些是项目试点指标，不是 WheelOS 已经实现的性能数据。</p><h3 id="_5-复盘优化-决定是否扩展" tabindex="-1">5. 复盘优化，决定是否扩展 <a class="header-anchor" href="#_5-复盘优化-决定是否扩展" aria-label="Permalink to &quot;5. 复盘优化，决定是否扩展&quot;">​</a></h3><table tabindex="0"><thead><tr><th>客户会看到</th><th>复盘内容</th><th>扩展条件</th><th>不扩展时</th></tr></thead><tbody><tr><td>证据包、指标对比、失败样本和剩余风险</td><td>业务价值、运行稳定性、成本、异常和安全边界</td><td>达到目标且具备增加车辆、线路或任务的条件</td><td>保留已验证经验，优化方案或重新评估</td></tr></tbody></table><h2 id="七个工程子步骤" tabindex="-1">七个工程子步骤 <a class="header-anchor" href="#七个工程子步骤" aria-label="Permalink to &quot;七个工程子步骤&quot;">​</a></h2><p>客户看到的是五个里程碑，内部可以继续拆成七个工程步骤：</p><table tabindex="0"><thead><tr><th>工程步骤</th><th>所属客户里程碑</th><th>主要输出</th></tr></thead><tbody><tr><td>场景调研</td><td>1</td><td>任务清单和初步价值测算</td></tr><tr><td>边界设计</td><td>2</td><td>运行设计域、责任矩阵和验收指标</td></tr><tr><td>车辆与传感器</td><td>3</td><td>硬件配置、接口清单和安装方案</td></tr><tr><td>软件与数据集成</td><td>3–4</td><td>配置、标定、数据记录和系统检查表</td></tr><tr><td>回放与受控场地验证</td><td>4</td><td>验证报告、失败案例和修复记录</td></tr><tr><td>试点运行</td><td>4</td><td>KPI、异常闭环和运行记录</td></tr><tr><td>评估与扩展</td><td>5</td><td>证据包、复盘和扩展建议</td></tr></tbody></table><h2 id="不跳阶段" tabindex="-1">不跳阶段 <a class="header-anchor" href="#不跳阶段" aria-label="Permalink to &quot;不跳阶段&quot;">​</a></h2><ul><li>底盘和线控接口未确认，不进入车辆集成承诺。</li><li>时间同步、坐标和标定未检查，不进入路线性能结论。</li><li>没有回放和失败样本，不进入场地验证结论。</li><li>没有基线和运营指标，不进入商业效果结论。</li><li>没有证据记录，不把试点升级为“已验证”或量产能力。</li></ul><h2 id="试点结束时的证据包" tabindex="-1">试点结束时的证据包 <a class="header-anchor" href="#试点结束时的证据包" aria-label="Permalink to &quot;试点结束时的证据包&quot;">​</a></h2><ol><li>任务和运行设计域。</li><li>软件、配置、车辆和传感器版本。</li><li>原始日志、录包和关键回放。</li><li>基线、目标值、实际指标和统计方法。</li><li>异常、接管、失败样本和整改记录。</li><li>未覆盖场景、法规边界和剩余风险。</li><li>复核人和下一阶段建议。</li></ol><div class="solution-cta"><div><h2>先选一条线路验证，再决定是否扩大</h2><p>从场景判断开始，明确任务、运行边界、车辆条件和试点指标。</p></div><div class="solution-actions"><a class="primary" href="/solutions/fit-assessment">开始场景适配判断</a><a href="/solutions/applications">查看六类应用场景</a></div></div>',23)])])}const f=e(o,[["render",h]]);export{p as __pageData,f as default};
